package com.hmdp.ai.runtime.node;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.TextNode;import com.hmdp.ai.domain.workflow.WorkflowNodeType;import com.hmdp.ai.shared.validation.JsonSchemaValidationService;import org.springframework.stereotype.Component;import java.util.*;
@Component public class InputNodeExecutor implements NodeExecutor {private final ObjectMapper mapper;private final JsonSchemaValidationService schemas;public InputNodeExecutor(ObjectMapper m,JsonSchemaValidationService s){mapper=m;schemas=s;}public Set<WorkflowNodeType>supportedTypes(){return EnumSet.of(WorkflowNodeType.INPUT_VALIDATION,WorkflowNodeType.INPUT_NORMALIZE);}public NodeExecutionResult execute(NodeExecutionContext c){if(c.getNode().getType()==WorkflowNodeType.INPUT_VALIDATION){JsonNode input=mapper.valueToTree(c.getVariables().get("input"));if(!schemas.validateValue(c.getWorkflow().getInputSchema(),input,"input").isValid())return NodeExecutionResult.failure("WORKFLOW_INPUT_INVALID",false);return NodeExecutionResult.success(input,null,null);}String text=String.valueOf(c.getVariables().getOrDefault("text","")).trim().replaceAll("\\s+"," ");return NodeExecutionResult.success(new TextNode(text),null,Collections.singletonMap("text",text));}}
